fn res_mix(acc: i64, value: i64, salt: i64) -> i64 with Mod {
    return ((acc * 16777619) + value + salt) % 1000000007
}

fn lit_abs(lit: i64) -> i64 {
    if lit < 0 { return 0 - lit }
    return lit
}

fn lit_complement(a: i64, b: i64) -> i64 {
    if a + b == 0 {
        if a != 0 { return 1 }
    }
    return 0
}

fn active_clause(id: i64, added5: i64, added6: i64, added7: i64) -> i64 {
    if id == 1 { return 1 } // x OR y
    if id == 2 { return 1 } // -x OR z
    if id == 3 { return 1 } // -y
    if id == 4 { return 1 } // -z
    if id == 5 { return added5 } // y OR z
    if id == 6 { return added6 } // z
    if id == 7 { return added7 } // empty
    return 0
}

fn clause_len(id: i64) -> i64 {
    if id == 1 { return 2 }
    if id == 2 { return 2 }
    if id == 3 { return 1 }
    if id == 4 { return 1 }
    if id == 5 { return 2 }
    if id == 6 { return 1 }
    if id == 7 { return 0 }
    return 0 - 1
}

fn clause_lit(id: i64, pos: i64) -> i64 {
    if id == 1 {
        if pos == 0 { return 1 }
        if pos == 1 { return 2 }
    }
    if id == 2 {
        if pos == 0 { return 0 - 1 }
        if pos == 1 { return 3 }
    }
    if id == 3 {
        if pos == 0 { return 0 - 2 }
    }
    if id == 4 {
        if pos == 0 { return 0 - 3 }
    }
    if id == 5 {
        if pos == 0 { return 2 }
        if pos == 1 { return 3 }
    }
    if id == 6 {
        if pos == 0 { return 3 }
    }
    return 0
}

fn contains_lit(id: i64, lit: i64) -> i64 {
    let n = clause_len(id)
    var i: i64 = 0
    while i < n {
        if clause_lit(id, i) == lit { return 1 }
        i = i + 1
    }
    return 0
}

fn output_contains(out0: i64, out1: i64, out_len: i64, lit: i64) -> i64 {
    if out_len >= 1 {
        if out0 == lit { return 1 }
    }
    if out_len >= 2 {
        if out1 == lit { return 1 }
    }
    return 0
}

fn output_tautology(out0: i64, out1: i64, out_len: i64) -> i64 {
    if out_len == 2 {
        return lit_complement(out0, out1)
    }
    return 0
}

fn output_duplicate(out0: i64, out1: i64, out_len: i64) -> i64 {
    if out_len == 2 {
        if out0 == out1 { return 1 }
    }
    return 0
}

fn check_resolution_step(p1: i64, p2: i64, pivot: i64,
                         out0: i64, out1: i64, out_len: i64,
                         added5: i64, added6: i64) -> i64 {
    if pivot <= 0 { return 0 }
    if out_len < 0 { return 0 }
    if out_len > 2 { return 0 }
    if active_clause(p1, added5, added6, 0) == 0 { return 0 }
    if active_clause(p2, added5, added6, 0) == 0 { return 0 }
    if output_tautology(out0, out1, out_len) == 1 { return 0 }
    if output_duplicate(out0, out1, out_len) == 1 { return 0 }

    var seen_pos: i64 = 0
    var seen_neg: i64 = 0
    if contains_lit(p1, pivot) == 1 { seen_pos = 1 }
    if contains_lit(p2, pivot) == 1 { seen_pos = 1 }
    if contains_lit(p1, 0 - pivot) == 1 { seen_neg = 1 }
    if contains_lit(p2, 0 - pivot) == 1 { seen_neg = 1 }
    if seen_pos != 1 { return 0 }
    if seen_neg != 1 { return 0 }

    var expected_count: i64 = 0
    var i: i64 = 0
    while i < clause_len(p1) {
        let lit = clause_lit(p1, i)
        if lit_abs(lit) != pivot {
            expected_count = expected_count + 1
            if output_contains(out0, out1, out_len, lit) == 0 { return 0 }
        }
        i = i + 1
    }
    i = 0
    while i < clause_len(p2) {
        let lit = clause_lit(p2, i)
        if lit_abs(lit) != pivot {
            expected_count = expected_count + 1
            if output_contains(out0, out1, out_len, lit) == 0 { return 0 }
        }
        i = i + 1
    }
    if expected_count != out_len { return 0 }
    return 1
}

fn sat_resolution_instance_fingerprint() -> i64 with Mod {
    var fp: i64 = 137
    fp = res_mix(fp, 3, 1301) // var count
    fp = res_mix(fp, 4, 1301) // base clause count
    fp = res_mix(fp, 3, 1301) // derived clause count
    fp = res_mix(fp, 0, 1301) // final clause length
    fp = res_mix(fp, 1, 1301) // pivots x,y,z
    fp = res_mix(fp, 2, 1301)
    fp = res_mix(fp, 3, 1301)
    return fp
}

fn sat_resolution_certificate_fingerprint(instance_fp: i64,
                                          ok5: i64, ok6: i64, ok7: i64) -> i64 with Mod {
    if instance_fp != 829764719 { return 0 - 1 }
    if ok5 != 1 { return 0 - 1 }
    if ok6 != 1 { return 0 - 1 }
    if ok7 != 1 { return 0 - 1 }

    var fp: i64 = 139
    fp = res_mix(fp, instance_fp, 1327)
    fp = res_mix(fp, 3, 1327)
    fp = res_mix(fp, 1, 1327)
    fp = res_mix(fp, 2, 1327)
    fp = res_mix(fp, 1, 1327)
    fp = res_mix(fp, 2, 1327)
    fp = res_mix(fp, 2, 1327)
    fp = res_mix(fp, 3, 1327)
    fp = res_mix(fp, 5, 1327)
    fp = res_mix(fp, 3, 1327)
    fp = res_mix(fp, 2, 1327)
    fp = res_mix(fp, 1, 1327)
    fp = res_mix(fp, 3, 1327)
    fp = res_mix(fp, 0, 1327)
    fp = res_mix(fp, 0, 1327)
    fp = res_mix(fp, 6, 1327)
    fp = res_mix(fp, 4, 1327)
    fp = res_mix(fp, 3, 1327)
    fp = res_mix(fp, 0, 1327)
    fp = res_mix(fp, 0, 1327)
    fp = res_mix(fp, 0, 1327)
    return fp
}

fn main() -> i64 {
    let ok5 = check_resolution_step(1, 2, 1, 2, 3, 2, 0, 0)
    let ok6 = check_resolution_step(5, 3, 2, 3, 0, 1, 1, 0)
    let ok7 = check_resolution_step(6, 4, 3, 0, 0, 0, 1, 1)
    let instance_fp = sat_resolution_instance_fingerprint()
    let cert_fp = sat_resolution_certificate_fingerprint(instance_fp, ok5, ok6, ok7)

    if ok5 != 1 { return 1 }
    if ok6 != 1 { return 2 }
    if ok7 != 1 { return 3 }
    if check_resolution_step(1, 2, 1, 3, 2, 2, 0, 0) != 1 { return 4 }
    if check_resolution_step(1, 2, 2, 2, 3, 2, 0, 0) != 0 { return 5 }
    if check_resolution_step(1, 2, 1, 2, 0 - 2, 2, 0, 0) != 0 { return 6 }
    if check_resolution_step(5, 3, 2, 3, 0, 1, 0, 0) != 0 { return 7 }
    if check_resolution_step(6, 4, 3, 0, 0, 0, 1, 0) != 0 { return 8 }
    if instance_fp != 829764719 { return 9 }
    if cert_fp != 177576187 { return 10 }
    if sat_resolution_certificate_fingerprint(instance_fp, ok5, 0, ok7) != (0 - 1) { return 11 }
    return 0
}

//@ run-pass
//@ expect-stdout: AUT OK
// FRENTE B — the automorphism group behind every 168, executed exactly.
//
// The 168 = |PSL(2,7)| that pervades the sedenion geometry (ZD census, non-Fano, fibers, quartets)
// IS a genuine group: the sedenion SIGNED-AUTOMORPHISM group. A linear map M in GL(4,2) (acting on
// indices 1..15 as F_2^4 vectors, preserving xor) is a signed automorphism iff the sign ratio
// sigma(Mi,Mj)*sigma(i,j) is a COBOUNDARY delta(eps)(i,j) = eps(i)eps(j)eps(i^j) for some signs eps.
// This test counts them exactly:
//   * octonions {1..7}: ALL 168 = |GL(3,2)| linear maps are signed automorphisms;
//   * sedenions {1..15}: exactly 168 of the |GL(4,2)| = 20160 linear maps are  (= the SAME 168);
//   * every sedenion automorphism FIXES e8 (index 8) — the doubling seam is the unique fixed point.
// So 168 is the group Aut ~ PSL(2,7); 1848 = 11*168 is NOT a group order (the 11 is combinatorial).
//
// Decidable F_2 linear algebra + integer signs, no float. SELF-CONTAINED. Cross-verified vs
// scripts/research/sedenion_automorphism_168_oracle.py by the matching gate + Lean file.

fn cd_sigma_c(a: i64, b: i64, bits: i64) -> i64 with Mut, Panic, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return 0 - 1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)
    let b_lo = b & (half - 1)
    if a_hi == 0 && b_hi == 0 { return cd_sigma_c(a_lo, b_lo, bits - 1) }
    if a_hi == 0 && b_hi == 1 { return cd_sigma_c(b_lo, a_lo, bits - 1) }
    if a_hi == 1 && b_hi == 0 {
        if b_lo == 0 { return cd_sigma_c(a_lo, 0, bits - 1) }
        return 0 - cd_sigma_c(a_lo, b_lo, bits - 1)
    }
    if b_lo == 0 { return 0 - cd_sigma_c(0, a_lo, bits - 1) }
    cd_sigma_c(b_lo, a_lo, bits - 1)
}

// popcount parity of a small int
fn par(x: i64) -> i64 with Mut, Panic, Div {
    var c = 0
    var b = 0
    while b < 8 {
        if (x & (1 << b)) != 0 { c = c + 1 }
        b = b + 1
    }
    c & 1
}

// M is d rows (m0..m3), each a d-bit int. Apply to vector x (d bits): bit r = parity(row_r & x).
fn apply(m0: i64, m1: i64, m2: i64, m3: i64, x: i64, d: i64) -> i64 with Mut, Panic, Div {
    var y = 0
    if par(m0 & x) == 1 { y = y | 1 }
    if par(m1 & x) == 1 { y = y | 2 }
    if d >= 3 { if par(m2 & x) == 1 { y = y | 4 } }
    if d >= 4 { if par(m3 & x) == 1 { y = y | 8 } }
    y
}

// F_2 rank of the d rows (d<=4) -> invertible iff rank == d.
fn invertible(m0: i64, m1: i64, m2: i64, m3: i64, d: i64) -> bool with Mut, Panic, Div {
    var r = [0; 4]
    r[0 as usize] = m0
    r[1 as usize] = m1
    r[2 as usize] = m2
    r[3 as usize] = m3
    var rank = 0
    var col = 0
    while col < d {
        var piv = 0 - 1
        var i = rank
        while i < d {
            if piv < 0 && (r[i as usize] & (1 << col)) != 0 { piv = i }
            i = i + 1
        }
        if piv >= 0 {
            let tmp = r[rank as usize]
            r[rank as usize] = r[piv as usize]
            r[piv as usize] = tmp
            var k = 0
            while k < d {
                if k != rank && (r[k as usize] & (1 << col)) != 0 { r[k as usize] = r[k as usize] ^ r[rank as usize] }
                k = k + 1
            }
            rank = rank + 1
        }
        col = col + 1
    }
    rank == d
}

// highest set bit of x>0 (x < 65536); returns 0 if x==0.
fn highbit(x: i64) -> i64 with Mut, Panic, Div {
    var h = 0
    var b = 0
    while b < 20 {
        if (x & (1 << b)) != 0 { h = b }
        b = b + 1
    }
    h
}

// Is M a signed automorphism? Build F_2 system a(i)+a(j)+a(i^j) = b(i,j) over vars 1..n-1,
// b = 0 if sigma(Mi,Mj)*sigma(i,j)=+1 else 1. RIGOROUS highest-variable-bit pivoting (order-
// independent): pivot[h] holds a mask whose variable part has highest bit h. Consistent => coboundary.
fn is_auto(m0: i64, m1: i64, m2: i64, m3: i64, d: i64) -> bool with Mut, Panic, Div {
    let n = 1 << d
    var pivmask = [0; 16]   // pivot for each variable-highbit column (var bits shifted: 0..n-2)
    var haspiv = [0; 16]
    var i = 1
    while i < n {
        let mi = apply(m0, m1, m2, m3, i, d)
        var j = i + 1
        while j < n {
            let mj = apply(m0, m1, m2, m3, j, d)
            let k = i ^ j
            let s = cd_sigma_c(mi, mj, d) * cd_sigma_c(i, j, d)
            var m = (1 << i) | (1 << j) | (1 << k)   // variable bits in positions 1..n-1
            if s < 0 { m = m | 1 }                    // bit 0 carries rhs (i,j,k >= 1 so bit0 free)
            // reduce: while the variable part (m>>1) is nonzero, pivot by its highest bit
            var done = 0
            var guard = 0
            while done == 0 && guard < n + 2 {
                let vpart = (m >> 1)
                if vpart == 0 {
                    if (m & 1) != 0 { return false }  // 0 = 1 inconsistent
                    done = 1
                } else {
                    let h = highbit(vpart)
                    if haspiv[h as usize] == 0 {
                        pivmask[h as usize] = m
                        haspiv[h as usize] = 1
                        done = 1
                    } else {
                        m = m ^ pivmask[h as usize]
                    }
                }
                guard = guard + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    true
}

fn count_autos(d: i64, require_fix8: i64) -> i64 with Mut, Panic, Div {
    let n = 1 << d
    var cnt = 0
    var m0 = 0
    while m0 < n {
        var m1 = 0
        while m1 < n {
            var m2 = 0
            let m2cap = if d >= 3 { n } else { 1 }
            while m2 < m2cap {
                var m3 = 0
                let m3cap = if d >= 4 { n } else { 1 }
                while m3 < m3cap {
                    if invertible(m0, m1, m2, m3, d) {
                        if is_auto(m0, m1, m2, m3, d) {
                            var ok = 1
                            if require_fix8 == 1 {
                                if apply(m0, m1, m2, m3, 8, d) != 8 { ok = 0 }
                            }
                            if ok == 1 { cnt = cnt + 1 }
                        }
                    }
                    m3 = m3 + 1
                }
                m2 = m2 + 1
            }
            m1 = m1 + 1
        }
        m0 = m0 + 1
    }
    cnt
}

fn main() with IO, Mut, Panic, Div {
    let oct = count_autos(3, 0)
    let sed = count_autos(4, 0)
    let sed_fix8 = count_autos(4, 1)
    print("OCT_AUTOS ")
    print_int(oct)
    print("\n")
    print("SED_AUTOS ")
    print_int(sed)
    print("\n")
    print("SED_FIX_E8 ")
    print_int(sed_fix8)
    print("\n")
    // octonion Aut = 168 = |GL(3,2)| ; sedenion Aut = 168 (same PSL(2,7)) ; ALL fix e8 (168 = 168).
    if oct == 168 && sed == 168 && sed_fix8 == 168 {
        println("AUT OK")
    } else {
        println("AUT FAIL")
    }
}

